def icon_html(icon_svg: str, text: str = "", color: str = "currentColor", size: int = 16) -> str:
    styled_icon = icon_svg.replace('width="16"', f'width="{size}"').replace('height="16"', f'height="{size}"')
    if text:
        return f'<div style="display:inline-flex; align-items:center; gap:6px; color:{color};">{styled_icon}<span>{text}</span></div>'
    return f'<div style="display:inline-flex; align-items:center; color:{color};">{styled_icon}</div>'
